import signal
import sys
import time

from picamera2 import Picamera2

running = True

def signal_handler(signum, frame):
    global running
    running = False

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

picam2 = None
try:
    picam2 = Picamera2()
    config = picam2.create_preview_configuration(
        main={"size": (640, 480), "format": "RGB888"}
    )
    picam2.configure(config)
    picam2.start()
    print("Camera initialized successfully.")
except Exception as e:
    print(f"Error initializing camera: {e}", file=sys.stderr)
    sys.exit(1)

try:
    while running:
        try:
            image = picam2.capture_array()
            if image is None:
                print("Warning: captured empty image.", file=sys.stderr)
                continue
            print(f"Captured image: {len(image)} bytes")
            with open("image.jpg", "wb") as f:
                f.write(image)
        except Exception as e:
            print(f"Error capturing image: {e}", file=sys.stderr)
            break
        time.sleep(1)
except KeyboardInterrupt:
    print("\nInterrupted by user.")
finally:
    if picam2 is not None:
        try:
            picam2.stop()
            print("Camera stopped.")
        except Exception as e:
            print(f"Error stopping camera: {e}", file=sys.stderr)
    print("Program finished.")

import serial
import time
import signal
import sys

SERIAL_PORT = '/dev/ttyS0'
BAUD_RATE = 9600
READ_TIMEOUT = 1.0

running = True

def signal_handler(signum, frame):
    global running
    running = False

def validate_reading(data):
    """Return True if the data is a valid integer, False otherwise."""
    try:
        int(data)
        return True
    except ValueError:
        return False

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    ser = None
    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=READ_TIMEOUT)
        print(f"Connected to {SERIAL_PORT} @ {BAUD_RATE} baud.")
        while running:
            try:
                raw = ser.readline()
                if not raw:
                    continue
                data = raw.decode('ascii', errors='replace').strip()
                if validate_reading(data):
                    print(f"Received: {data}")
            except serial.SerialException as e:
                print(f"Serial read error: {e}", file=sys.stderr)
                break
            except Exception as e:
                print(f"Unexpected error: {e}", file=sys.stderr)
                break
            time.sleep(0.5)
    except serial.SerialException as e:
        print(f"Failed to open serial port {SERIAL_PORT}: {e}", file=sys.stderr)
        sys.exit(1)
    finally:
        if ser is not None and ser.is_open:
            ser.close()
            print("Serial port closed.")

if __name__ == '__main__':
    main()

import time
import signal
import sys
from gpiozero import DigitalOutputDevice

# BCM GPIO pin connected to the digital output
OUTPUT_PIN = 17

# Number of cycles to run
NUM_CYCLES = 5

# Global reference so the signal handler can release the device
_output = None

def cleanup(signum=None, frame=None):
    """Release the GPIO device and exit cleanly."""
    global _output
    if _output is not None:
        try:
            _output.close()
        except Exception:
            pass
        _output = None
    if signum is not None:
        sys.exit(0)

def main():
    global _output

    # Register signal handlers for clean shutdown
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    # Initialize the digital output device
    try:
        _output = DigitalOutputDevice(OUTPUT_PIN)
    except Exception as e:
        print(f"Failed to initialize GPIO {OUTPUT_PIN}: {e}", file=sys.stderr)
        sys.exit(1)

    print(f"Digital output on GPIO {OUTPUT_PIN} initialized. Running {NUM_CYCLES} cycles.")

    try:
        for i in range(NUM_CYCLES):
            if i < NUM_CYCLES:
                # gpiozero uses 0 for False, 1 for True
                _output.value = 1
                print(f"Cycle {i + 1}: Output is {_output.value}")
            else:
                print(f"Cycle {i + 1}: Output is already {_output.value}")

            time.sleep(2)

    except KeyboardInterrupt:
        print("\nInterrupted by user.")
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        cleanup()

if __name__ == "__main__":
    main()

import signal
import sys
import time

from gpiozero import DigitalOutputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

# BCM pin number for the digital output (GPIO 17)
OUTPUT_PIN = 17

# Global reference so the signal handler can release the device.
_device = None


def cleanup(signum=None, frame=None):
    """Release the GPIO device and close the underlying GPIO backend."""
    global _device
    if _device is not None:
        try:
            _device.close()
        except DeviceClosed:
            pass
        _device = None
    if signum is not None:
        sys.exit(0)


def main():
    global _device

    # Register signal handlers for graceful shutdown on SIGINT / SIGTERM.
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        _device = DigitalOutputDevice(OUTPUT_PIN, active_high=True, initial_value=False)
    except GPIOZeroError as exc:
        print(f"Error: failed to initialize GPIO {OUTPUT_PIN}: {exc}", file=sys.stderr)
        sys.exit(1)

    print(f"Digital output on BCM GPIO {OUTPUT_PIN} initialized (active=HIGH, initial=False).")

    try:
        while True:
            try:
                _device.value = True
                print("Output ON")
            except DeviceClosed:
                print("Device closed; cannot write.", file=sys.stderr)
                break
            except GPIOZeroError as exc:
                print(f"GPIO error: {exc}", file=sys.stderr)
                break
            time.sleep(0.1)
    except KeyboardInterrupt:
        print("\nInterrupted by user.")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

import signal
import sys
import time

from gpiozero import PWMOutputDevice
from gpiozero.exc import GPIOZeroError

PWM_PIN_1 = 12
PWM_PIN_2 = 20
PWM_PIN_3 = 21
REPEAT_INTERVAL = 0.03

pwm_pins = [PWM_PIN_1, PWM_PIN_2, PWM_PIN_3]

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    pwm_devices = []
    try:
        for pin in pwm_pins:
            try:
                pwm = PWMOutputDevice(pin, frequency=1000)
                pwm.value = 0.0
                pwm_devices.append(pwm)
            except GPIOZeroError as exc:
                print(f"Error: failed to initialize PWM on GPIO {pin}: {exc}", file=sys.stderr)
                sys.exit(1)
        print("PWM devices initialized successfully.")

        while _running:
            for pwm in pwm_devices:
                try:
                    pwm.value = 0.5
                except GPIOZeroError as exc:
                    print(f"Warning: failed to set PWM value: {exc}", file=sys.stderr)
            time.sleep(REPEAT_INTERVAL)

    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
    finally:
        for pwm in pwm_devices:
            try:
                pwm.value = 0.0
                pwm.close()
            except Exception:
                pass
        print("GPIO cleanup completed.")


if __name__ == "__main__":
    main()

