import smbus2
import sys

I2C_ADDRESS = 0x68

def main():
    bus = None
    try:
        bus = smbus2.SMBus(1)
    except FileNotFoundError:
        print("Error: I2C bus 1 not found. Enable I2C with 'sudo raspi-config'.", file=sys.stderr)
        sys.exit(1)
    except PermissionError:
        print("Error: Permission denied opening I2C bus. Run as root or add user to 'i2c' group.", file=sys.stderr)
        sys.exit(1)

    try:
        bus.read_byte(I2C_ADDRESS)
    except OSError as e:
        print(f"Error: No device found at 0x{I2C_ADDRESS:02X} on bus 1. "
              f"Check wiring and address. ({e})", file=sys.stderr)
        sys.exit(1)

    print("MPU6050 detected at 0x{0:02X} on bus 1. Reading measurements...")
    try:
        while True:
            try:
                accel_x = bus.read_byte_data(I2C_ADDRESS, 0x3B)
                accel_y = bus.read_byte_data(I2C_ADDRESS, 0x3C)
                accel_z = bus.read_byte_data(I2C_ADDRESS, 0x3D)
                gyro_x = bus.read_byte_data(I2C_ADDRESS, 0x3E)
                gyro_y = bus.read_byte_data(I2C_ADDRESS, 0x3F)
                gyro_z = bus.read_byte_data(I2C_ADDRESS, 0x40)

                print(f"Accel X: {accel_x:6.2f}, Accel Y: {accel_y:6.2f}, Accel Z: {accel_z:6.2f}")
                print(f"Gyro X: {gyro_x:6.2f}, Gyro Y: {gyro_y:6.2f}, Gyro Z: {gyro_z:6.2f}")

            except OSError as e:
                print(f"I2C read error: {e}. Retrying in 1 second...", file=sys.stderr)
                sys.exit(1)

            time.sleep(1)

    except KeyboardInterrupt:
        print("\nProgram interrupted by user.")
    finally:
        if bus is not None:
            try:
                bus.close()
            except Exception:
                pass
        print("I2C bus released. Exiting.")

if __name__ == "__main__":
    main()

