import signal
import sys
import time

from gpiozero import PWMOutputDevice
from gpiozero.exc import GPIOZeroError, GPIODeviceError

# BCM pin numbers (BCM numbering)
PWM_PINS = [4, 17, 22, 27]

# Global reference so the signal handler can release the device.
_pwm_devices = []


def cleanup(signum=None, frame=None):
    """Release all PWM devices and close the gpiozero backend."""
    for dev in _pwm_devices:
        try:
            dev.close()
        except Exception:
            pass
    _pwm_devices.clear()
    if signum is not None:
        sys.exit(0)


def main():
    global _pwm_devices

    # Register signal handlers for clean shutdown.
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    # gpiozero PWMOutputDevice expects BCM numbering by default.
    # The list is populated by the signal handler so we can report
    # the error and exit cleanly.
    try:
        _pwm_devices = [PWMOutputDevice(pin, frequency=1000, initial_value=0) for pin in PWM_PINS]
    except (GPIOZeroError, GPIODeviceError) as exc:
        print(f"Error: failed to initialize PWM on GPIO {', '.join(PWM_PINS)}: {exc}", file=sys.stderr)
        cleanup()
        sys.exit(1)

    print("PWM output initialized on GPIO 4, 17, 22, 27 (BCM).  "
          "Press Ctrl+C to stop.")

    try:
        while True:
            for dev in _pwm_devices:
                try:
                    dev.value = 1.0  # 100% duty cycle
                except Exception as exc:
                    print(f"Warning: failed to set duty cycle on {dev.pin.name}: {exc}", file=sys.stderr)
            time.sleep(1)
    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

