import signal
import sys
import time

from gpiozero import PWMOutputDevice
from gpiozero.exc import GPIOZeroError, GPIODeviceError

PWM_FREQUENCIES = {
    12: 50,
    13: 50,
    18: 50,
    19: 50,
    22: 50,
    23: 50,
}

PWM_OUTPUTS = {
    12: PWMOutputDevice(pin=12, frequency=PWM_FREQUENCIES[12]),
    13: PWMOutputDevice(pin=13, frequency=PWM_FREQUENCIES[13]),
    18: PWMOutputDevice(pin=18, frequency=PWM_FREQUENCIES[18]),
    19: PWMOutputDevice(pin=19, frequency=PWM_FREQUENCIES[19]),
    22: PWMOutputDevice(pin=22, frequency=PWM_FREQUENCIES[22]),
    23: PWMOutputDevice(pin=23, frequency=PWM_FREQUENCIES[23]),
}


def apply_pwm(pwm, duty_cycle):
    """Apply a duty cycle to the PWM output; return True on success."""
    try:
        pwm.value = duty_cycle / 100.0
        return True
    except (GPIOZeroError, GPIODeviceError) as exc:
        print(f"Error applying PWM: {exc}", file=sys.stderr)
        return False


def report_pwm_state(pwm, name, duty_cycle):
    """Report the PWM state for a given GPIO pin."""
    if apply_pwm(pwm, duty_cycle):
        print(f"{name} PWM: {duty_cycle:.1f}%")
    else:
        print(f"{name} PWM: failed to apply")


def cleanup(pwm_devices):
    """Release all PWM devices and close the GPIO backend."""
    for name, pwm in pwm_devices.items():
        try:
            pwm.close()
        except Exception:
            pass
    print("GPIO cleanup complete.")


def main():
    pwm_devices = {}
    try:
        for name, pwm in PWM_OUTPUTS.items():
            pwm_devices[name] = pwm
        print("PWM outputs initialized.")

        signal.signal(signal.SIGINT, lambda s, f: sys.exit(0))
        signal.signal(signal.SIGTERM, lambda s, f: sys.exit(0))

        while True:
            for name, pwm in PWM_OUTPUTS.items():
                if not apply_pwm(pwm, 50):
                    print(f"{name} PWM: failed to apply")
                    break
            report_pwm_state(pwm_devices[name], name, 50)
            time.sleep(2)

    except KeyboardInterrupt:
        print("\nInterrupted by user.")
    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
    finally:
        cleanup(pwm_devices)


if __name__ == "__main__":
    main()

import time
import signal
import sys
import smbus2

# I2C address of the PCF8574 I/O expander on the Raspberry Pi
I2C_ADDRESS = 0x27

# PCF8574 register addresses
REG_DATA = 0x00
REG_CONFIG = 0x01

# Global flag for graceful shutdown
running = True

def signal_handler(sig, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global running
    running = False

def read_pcf8574(bus):
    """Read a byte from the PCF8574. Returns None on error."""
    try:
        data = bus.read_byte_data(I2C_ADDRESS, REG_DATA)
        return data
    except OSError as e:
        print(f"I2C read error at 0x{I2C_ADDRESS:02X}: {e}")
        return None

def validate_pcf8574(data):
    """Return True if the PCF8574 is responding, False otherwise."""
    if data is None:
        return False
    return (data & 0x80) == 0

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    bus = None
    try:
        bus = smbus2.SMBus(1)  # /dev/i2c-1 on Raspberry Pi
        print("PCF8574 I/O expander initialized at 0x{:02X}".format(I2C_ADDRESS))

        while running:
            data = read_pcf8574(bus)
            if data is None:
                print("Warning: PCF8574 not responding (bus error)")
            else:
                if validate_pcf8574(data):
                    print("PCF8574: 0x{:02X}".format(data))
                else:
                    print("Warning: PCF8574 data invalid (not responding)")

            # Sleep in small increments so signals are caught promptly
            slept = 0
            while running and slept < 2:
                time.sleep(0.1)
                slept += 0.1

    except OSError as e:
        print(f"I2C bus error: {e}")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        if bus is not None:
            try:
                bus.close()
                print("I2C bus closed.")
            except Exception:
                pass
        print("Program terminated.")

if __name__ == "__main__":
    main()

