SG90_PIN = 18
REPEAT_INTERVAL = 0.5

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def main():
    global _running
    _running = True

    # Register signal handlers for clean shutdown on SIGINT (Ctrl-C) and SIGTERM
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        sg90 = OutputDevice(SG90_PIN, active_high=True, initial_value=False)
    except (GPIOZeroError, GPIODeviceError) as exc:
        print(f"Error: Failed to initialize SG90 on GPIO {SG90_PIN}: {exc}", file=sys.stderr)
        sys.exit(1)

    print(f"SG90 on GPIO {SG90_PIN} initialized. Press Ctrl-C to exit.")

    try:
        while _running:
            try:
                applied = sg90.value
            except (GPIOZeroError, GPIODeviceError) as exc:
                print(f"Warning: Failed to read SG90 state: {exc}", file=sys.stderr)
                time.sleep(REPEAT_INTERVAL)
                continue

            if applied:
                print("SG90 ON")
            else:
                print("SG90 OFF")

            time.sleep(REPEAT_INTERVAL)

    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
    finally:
        try:
            sg90.close()
        except Exception:
            pass
        print("GPIO cleanup done.")

if __name__ == "__main__":
    main()

import serial
import time
import signal
import sys

SERIAL_PORT = '/dev/ttyS0'
BAUD_RATE = 9600
RETRY_DELAY = 0.5

running = True

def signal_handler(signum, frame):
    global running
    running = False

def validate_reading(data):
    """Return True if the data is a valid integer, False otherwise."""
    try:
        int(data)
        return True
    except ValueError:
        return False

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    ser = None
    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=1)
        print(f"Connected to {SERIAL_PORT} @ {BAUD_RATE} baud.")
        while running:
            try:
                raw = ser.readline()
                if not raw:
                    continue
                data = raw.decode('ascii', errors='replace').strip()
                if validate_reading(data):
                    print(f"Received: {data}")
            except serial.SerialException as e:
                print(f"Serial read error: {e}", file=sys.stderr)
                break
            except Exception as e:
                print(f"Unexpected error: {e}", file=sys.stderr)
                break
            time.sleep(RETRY_DELAY)
    except serial.SerialException as e:
        print(f"Failed to open serial port {SERIAL_PORT}: {e}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
        sys.exit(1)
    finally:
        if ser is not None and ser.is_open:
            ser.close()
            print("Serial port closed.")

if __name__ == '__main__':
    main()

