import signal
import sys
import time

from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

# BCM pin numbers (BCM numbering)
OUTPUT_PINS = [4, 17, 18, 22, 23, 24, 25, 27]

# Validate a reading is a number between 0 and 1.
def validate_reading(reading):
    if not isinstance(reading, (int, float)) or not 0 <= reading <= 1:
        raise ValueError(f"Reading must be a number between 0 and 1, got {reading!r}")

def main():
    # gpiozero OutputDevice handles the GPIO pin and its internal state.
    # It raises GPIOZeroError on hardware failure or when the pin is already in use.
    devices = []
    try:
        for pin in OUTPUT_PINS:
            dev = OutputDevice(pin)
            devices.append(dev)

        print("Starting digital output control loop. Press Ctrl+C to exit.")

        while True:
            for dev in devices:
                try:
                    state = dev.value
                    validate_reading(state)
                    print(f"GPIO {pin}: {state:.2f}")
                except GPIOZeroError as exc:
                    print(f"GPIO error on pin {pin}: {exc}", file=sys.stderr)
                    break
                except Exception as exc:
                    print(f"Unexpected error on pin {pin}: {exc}", file=sys.stderr)
                    break

            time.sleep(0.001)

    except KeyboardInterrupt:
        print("\nInterrupted by user.")
    except Exception as exc:
        print(f"Fatal error: {exc}", file=sys.stderr)
    finally:
        for dev in devices:
            try:
                dev.close()
            except Exception:
                pass

if __name__ == "__main__":
    main()

