import signal
import sys
import time

from gpiozero import DigitalOutputDevice
from gpiozero.exc import GPIOZeroError, GPIODeviceError

# BCM pin numbers (BCM numbering)
OUTPUT_PINS = [5, 6, 12]

# Valid state: 0 (off), 1 (on)
VALID_STATES = [0, 1]


def apply_output(device: DigitalOutputDevice, state: int) -> None:
    """Apply *state* to the digital output and report its current value."""
    try:
        device.value = state
        print(f"Applied: {state} -> GPIO {device.pin.number}")
    except (GPIOZeroError, GPIODeviceError) as exc:
        print(f"Error applying output: {exc}", file=sys.stderr)
        raise


def main() -> None:
    """Run the 3-cycle output-control loop and release the GPIO device."""
    devices: list[DigitalOutputDevice] = []

    for pin in OUTPUT_PINS:
        try:
            devices.append(DigitalOutputDevice(pin))
        except (GPIOZeroError, GPIODeviceError) as exc:
            print(f"Failed to initialize GPIO {pin}: {exc}", file=sys.stderr)
            sys.exit(1)

    # Ensure all devices are closed on exit
    try:
        for dev in devices:
            dev.close()
    except Exception:
        pass

    # Graceful shutdown on SIGTERM (e.g., systemd stop)
    def _shutdown(signum, frame):
        print("\nShutdown signal received, cleaning up...")
        for dev in devices:
            try:
                dev.close()
            except Exception:
                pass
        sys.exit(0)

    signal.signal(signal.SIGTERM, _shutdown)

    try:
        for cycle in range(3):
            apply_output(devices[0], VALID_STATES[cycle % len(VALID_STATES)])
            time.sleep(0.5)
    except KeyboardInterrupt:
        print("\nInterrupted by user.")
    finally:
        # Ensure all devices are closed on exit
        for dev in devices:
            try:
                dev.close()
            except Exception:
                pass


if __name__ == "__main__":
    main()

import signal
import sys
import time

from gpiozero import DigitalOutputDevice
from gpiozero.exc import GPIOZeroError

# BCM pin numbers for the digital output
OUTPUT_PIN_1 = 17
OUTPUT_PIN_2 = 18

# Global reference so the signal handler can release the device.
_output_device = None


def cleanup(signum=None, frame=None):
    """Release the GPIO device and exit cleanly."""
    global _output_device
    if _output_device is not None:
        try:
            _output_device.close()
        except Exception:
            pass
        _output_device = None
    if signum is not None:
        sys.exit(0)


def main():
    global _output_device

    # Register signal handlers for graceful shutdown.
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        _output_device = DigitalOutputDevice(
            OUTPUT_PIN_1, active_high=True, initial_value=False
        )
    except GPIOZeroError as exc:
        print(f"Failed to initialize GPIO device on pin {OUTPUT_PIN_1} or {OUTPUT_PIN_2}: {exc}", file=sys.stderr)
        sys.exit(1)

    print(f"Digital output on BCM pins {OUTPUT_PIN_1} and {OUTPUT_PIN_2} initialized.")

    try:
        while True:
            try:
                _output_device.value = True
                print("Output ON")
            except GPIOZeroError as exc:
                print(f"GPIO error while setting output: {exc}", file=sys.stderr)
                break

            time.sleep(1)
    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
    finally:
        cleanup()


if __name__ == "__main__":
