import signal
import sys
import time

import paho.mqtt.client as mqtt

MQTT_BROKER = "localhost"
MQTT_PORT = 1883
MQTT_TOPIC = "sensor_readings"
READINGS_COUNT = 3
READING_INTERVAL = 1.0

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def on_connect(client, userdata, flags, reason_code, properties):
    if reason_code == 0:
        print("Connected to MQTT broker.")
    else:
        print(f"Failed to connect to MQTT broker, reason code: {reason_code}")


def on_disconnect(client, userdata, flags, reason_code, properties):
    print(f"Disconnected from MQTT broker, reason code: {reason_code}")


def publish_reading(client, reading):
    try:
        client.publish(MQTT_TOPIC, str(reading), qos=1)
        print(f"Published reading: {reading}")
    except Exception as e:
        print(f"Error publishing reading: {e}")


def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    client = mqtt.Client(mqtt.CallbackAPIVersion.VERSION2)
    client.on_connect = on_connect
    client.on_disconnect = on_disconnect

    try:
        client.connect(MQTT_BROKER, MQTT_PORT, keepalive=60)
        client.loop_start()
        for i in range(READINGS_COUNT):
            if not _running:
                break
            reading = i * 10
            publish_reading(client, reading)
            if i < READINGS_COUNT - 1:
                time.sleep(READING_INTERVAL)
    except Exception as e:
        print(f"Error: {e}")
    finally:
        client.loop_stop()
        client.disconnect()
        print("Exiting program.")


if __name__ == "__main__":
    main()

import signal
import sys
import time

from gpiozero import PWMOutputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

PWM_PIN = 14
REPEAT_INTERVAL = 5.0

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def validate_reading(value):
    """Return True if the value is a valid PWM duty cycle (0.0-1.0)."""
    return 0.0 <= value <= 1.0


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        pwm = PWMOutputDevice(PWM_PIN, frequency=1000)
    except GPIOZeroError as exc:
        print(f"Error: failed to initialize PWM on GPIO {PWM_PIN}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            try:
                duty = pwm.value
            except DeviceClosed:
                print("Error: device closed unexpectedly.", file=sys.stderr)
                break
            except GPIOZeroError as exc:
                print(f"Error: GPIO read failed: {exc}", file=sys.stderr)
                break

            if not validate_reading(duty):
                print(f"Warning: invalid duty cycle {duty:.2f} (expected 0.0-1.0).", file=sys.stderr)
                continue

            print(f"Duty cycle: {duty:.2f}")
            time.sleep(REPEAT_INTERVAL)
    finally:
        try:
            pwm.close()
        except DeviceClosed:
            pass


if __name__ == "__main__":
    main()

import signal
import sys
from gpiozero import PWMOutputDevice

# BCM pin number for the PWM output (BCM numbering)
PWM_PIN = 12

# Global reference so the signal handler can release the device.
_pwm_device: PWMOutputDevice | None = None


def cleanup() -> None:
    """Release the PWM output device and close the gpiozero device."""
    global _pwm_device
    if _pwm_device is not None:
        try:
            _pwm_device.close()
        except Exception:
            pass
        _pwm_device = None


def _handle_signal(signum, frame) -> None:
    """Handle SIGINT / SIGTERM by releasing the PWM device."""
    cleanup()
    sys.exit(0)


def main() -> None:
    """Drive a PWM output on BCM GPIO 12 and report its state."""
    global _pwm_device

    # Register signal handlers for clean shutdown.
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        _pwm_device = PWMOutputDevice(PWM_PIN, frequency=1000)
        print(f"PWM output on BCM GPIO {PWM_PIN} (1000 Hz) initialized.")
    except Exception as exc:
        print(f"Error initializing PWM output: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while True:
            try:
                _pwm_device.value = 0.5  # 50% duty cycle
                print("PWM output set to 50% duty cycle.")
            except Exception as exc:
                print(f"Error setting PWM output: {exc}", file=sys.stderr)
                break

            # Sleep in small increments so signals are caught promptly.
            slept = 0.0
            while slept < 10.0:
                if _pwm_device is not None:
                    try:
                        _pwm_device.value = 0.5
                        slept += 0.1
                    except Exception as exc:
                        print(f"Warning: failed to update PWM output: {exc}",
                              file=sys.stderr)
                        break
                else:
                    break
            else:
                print("Warning: PWM output not updated within 10 s.",
                      file=sys.stderr)

    finally:
        cleanup()


if __name__ == "__main__":
    main()

