    for cycle in range(5):
        if not running:
            break
        print(f"Capture {cycle + 1}/5")
        if not capture_and_save("image_{cycle}.jpg"):
            break
        time.sleep(0.5)

if __name__ == "__main__":
    main()

import signal
import sys
import time

from luma.core.interface.serial import i2c
from luma.oled.device import ssd1306
from luma.core.render import canvas

SCREEN_WIDTH = 128
SCREEN_HEIGHT = 64

serial_port = None
display = None
running = True

def cleanup():
    global display
    if display is not None:
        try:
            display.clear()
        except Exception:
            pass
        display = None
    if serial_port is not None:
        try:
            serial_port.close()
        except Exception:
            pass
        serial_port = None

def signal_handler(signum, frame):
    global running
    running = False

def main():
    global serial_port, display

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        serial_port = i2c(port=1, address=0x3C)
    except Exception as e:
        print(f"Error: Could not open I2C bus 1 at 0x3C: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        display = ssd1306(serial_port, width=SCREEN_WIDTH, height=SCREEN_HEIGHT)
    except Exception as e:
        print(f"Error: Could not initialize SSD1306 display: {e}", file=sys.stderr)
        cleanup()
        sys.exit(1)

    try:
        while running:
            try:
                display.text("Temp: {:.1f} C".format(display.temperature), 0, 0, 1)
                display.text("Humidity: {:.1f} %".format(display.humidity), 0, 16, 1)
                display.show()
            except Exception as e:
                print(f"Error displaying data: {e}", file=sys.stderr)
            time.sleep(0.1)
    finally:
        cleanup()

if __name__ == "__main__":
    main()

import signal
import sys
import time

from gpiozero import PWMOutputDevice
from gpiozero.exc import GPIOZeroError, GPIODeviceError

PWM_PIN = 18

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        pwm = PWMOutputDevice(PWM_PIN, frequency=1000)
    except (GPIOZeroError, GPIODeviceError) as exc:
        print(f"Error: failed to initialize PWM on GPIO {PWM_PIN}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            try:
                pwm.value = 0.5
                state = "ON"
            except (GPIOZeroError, GPIODeviceError) as exc:
                print(f"Warning: failed to apply PWM: {exc}", file=sys.stderr)
                break

            print(f"PWM {PWM_PIN} -> {state}")
            time.sleep(0.1)
    finally:
        try:
            pwm.close()
        except Exception:
            pass

if __name__ == "__main__":
    main()

import time
import signal
import sys
import smbus2

# ADXL345 I2C address (default for ADXL345)
ADXL345_ADDR = 0x1D

# Global handle so the signal handler can release the bus
_bus = None

def _cleanup(signum=None, frame=None):
    """Release the I2C bus and exit cleanly."""
    global _bus
    if _bus is not None:
        try:
            _bus.close()
        except Exception:
            pass
        _bus = None
    if signum is not None:
        sys.exit(0)

def read_adxl345(bus):
    """Read a single measurement from the ADXL345.

    Returns (x, y, z) or (None, None, None) on error.
    """
    try:
        # Read 3 bytes: 2 for the register address, 1 for the data register
        data = bus.read_i2c_block_data(ADXL345_ADDR, 0x32, 3)
        if len(data) != 3:
            print(f"Warning: unexpected data length: {len(data)}")
            return None, None, None

        # Combine the two bytes into a 16-bit value
        value = (data[0] << 8) | data[1]
        return value, None, None
    except OSError as e:
        print(f"I2C read error: {e}")
        return None, None, None

def main():
    global _bus

    # Register signal handlers for clean shutdown
    signal.signal(signal.SIGINT, _cleanup)
    signal.signal(signal.SIGTERM, _cleanup)

    # Open the I2C bus
    try:
        _bus = smbus2.SMBus(1)
    except OSError as e:
        print(f"Error: cannot open I2C bus 1: {e}")
        sys.exit(1)

    try:
        while True:
            x, y, z = read_adxl345(_bus)
            if x is not None and y is not None and z is not None:
                print(f"ADXL345: x={x}, y={y}, z={z}")
            else:
                print("Error: failed to read ADXL345 data")
            time.sleep(1)
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        _cleanup()

if __name__ == "__main__":
    main()
